app.service('RecruitmentJobsService', [ 'utilityService', '$sce',
    function (utilityService, $sce) {
        'use strict';

        var self = this;

        this.url = {
            content: 'recruitment-frontend/external-company-job-page/2',
            additionalField: 'recruitment-frontend/addition-field-candidate-detail',
            saveAdditionalField: 'recruitment-frontend/save-addition-stage-fields',
            termsAndPolicies: 'recruitment/data-retention-policy-content',
            dataRetentionPolicy: 'recruitment/data-retention-content',
            acceptExtendPolicy: 'recruitment-frontend/extend-retention-period'
        };
        this.getUrl = function (apiUrl) {
            return getAPIPath() + this.url[apiUrl];
        };
        this.loadTeamCarousel = function () {
            $("#team-list").owlCarousel({
                items: 3,
                loop: true,
                lazyLoad: true,
                navText: ["<i class='fa fa-angle-left fa-lg'></i>","<i class='fa fa-angle-right fa-lg'></i>"],
                pagination: false,
                nav: true,
                dots: false,
                margin: 10
            });
        };

    }
]);

app.controller('RecruitmentJobsController', [
    '$scope', '$timeout', '$routeParams', 'utilityService', 'RecruitmentJobsService', 'ServerUtilityService', '$anchorScroll', '$location', 'JobCommonService', '$modal', '$mdDialog',
    function ($scope, $timeout, $routeParams, utilityService, service, serverUtilityService, $anchorScroll, $location, JobCommonService, $modal, $mdDialog) {
        'use strict';
        var self = this;
        $scope.errorMessages = [];
        $scope.additionalFieldSection = {
            pageVisible: false,
            pageExpire: false,
            job_id: utilityService.getValue($routeParams, 'job_id', null),
            candidate_id: utilityService.getValue($routeParams, 'candidate_id', null),
            application_fields: null,
            additional_fields: [],
            job_details: null,
            pattern: {
                email: /^[a-zA-Z0-9-]+[a-zA-Z0-9._-]+@[a-zA-Z-]+\.[a-zA-Z.-]{2,20}$/,
                alphaNumeric: /^[0-9a-zA-Z \b]+$/
            }
        };
        $scope.termsNcondition = false;
        $scope.pages = null;
        $scope.banner = {
            content: null
        };
        $scope.viewJobList = {
            visible: false,
            no_section: false,
        };
        $scope.policies = {
            termsNcondition: {
                check: false,
                content: null
            },
            dataRetention: {
                check: false,
                content: null,
                content_extended: null,
            },

        }
        // $scope.socialLinks = {
        //     linkedin : $scope.envMnt === 'local' 
        //         ? 'https://in.linkedin.com/company/shadowfax' : '#/',
        //     facebook: $scope.envMnt === 'local' 
        //         ? 'https://in.linkedin.com/company/shadowfax' : '#/',
        //     twitter: $scope.envMnt === 'local' 
        //         ? 'https://in.linkedin.com/company/shadowfax' : '#/',
        //     instagram: $scope.envMnt === 'local' 
        //         ? 'https://in.linkedin.com/company/shadowfax' : '#/',
        // };

        $scope.isAdditionalFieldSectionActive = function() {
            return $scope.additionalFieldSection.job_id && $scope.additionalFieldSection.candidate_id;
        };
        $scope.setBannerTitle = function (JobDetail) {
            var iconDiv = document.getElementById('jobsIcons');
            var depIconDiv = document.getElementById('jobsIconsDep');
            if(angular.isDefined(JobDetail)) {
                $scope.banner.description = null;
                var dep = JobDetail.body.find(function(elem) { return elem.slug === 'work_profile_department';});
                $scope.banner.selectedJob = {
                    title: JobDetail.head.job_title.value,
                    location: JobDetail.head.location,
                    department: dep ? dep.value : null
                };
                if(iconDiv) {
                    iconDiv.style.visibility = 'visible';
                }
                if(depIconDiv) {
                    depIconDiv.style.visibility = dep ? 'visible' : 'hidden';
                }
            } else {
                $scope.banner.selectedJob = {
                    title: null,
                    location: null,
                    department: null
                };
                $scope.banner.description = $scope.banner.title;
                if(iconDiv) {
                    iconDiv.style.visibility = 'hidden';
                }
                if(depIconDiv) {
                    depIconDiv.style.visibility = 'hidden';
                }
            }
        };        
        var pageContentCallback = function (data) {
            var pageData = utilityService.getValue(data, 'data') ? data.data : [];
            var bannerData = pageData.find(function(elem) {
                return elem.slug === 'banner';
            });
            $scope.banner = bannerData ? bannerData : $scope.banner;
            $scope.pages = pageData;
            if(!pageData.length) {
                $scope.viewJobList.no_section = true;
            }
            $scope.setBannerTitle();
            $timeout(function () {
                service.loadTeamCarousel();
            }, 1000);
        };
        var getPageContent = function() {
            serverUtilityService.getWebService(service.getUrl('content'))
                .then(function(data){
                    pageContentCallback(data);
                });
        };
        var getyoutubeVidId = function(url) {
            var regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
            var match = url.match(regExp);

            if (match && match[2].length === 11) {
                return match[2];
            } else {
                return 'QELAhddrs4s';
            }
        };
        $scope.createIFrame = function(url) {
            var id = getyoutubeVidId(url);
            return '<iframe width="640" height="360" src="//www.youtube.com/embed/' + id + '" frameborder="0" allow="autoplay; encrypted-media" allowfullscreen></iframe>'
        };
        $scope.scrollTo = function(id) {
            $location.hash(id);
            $anchorScroll();
        };
        $scope.isSection = function(section) {
            if(!angular.isArray($scope.pages) || !section) { return false; }
            if(section === 'any_section') {
                return $scope.pages.length ? true : false;
            }
            var ind = $scope.pages.findIndex(function(elem) {return elem.slug === section;});
            return (ind === -1) ? false : true;
        };
        $scope.homePageRedirect = function() {
            $location.url("dashboard/home");
        };
        $scope.goToDefaultJobs = function() {
            $scope.additionalFieldSection.job_id = null;
            $scope.additionalFieldSection.candidate_id = null;
            $location.search('job_id', null);
            $location.search('candidate_id', null);
            getPageContent();
        };
        var getAdditionalFields = function(cb) {
            var url = service.getUrl('additionalField') + '/' + $scope.additionalFieldSection.candidate_id + '/' + $scope.additionalFieldSection.job_id;
            serverUtilityService.getWebService(url)
                .then(function(data){
                    $scope.additionalFieldSection.job_details = utilityService.getInnerValue(data, 'data', 'job_details', null);
                    $scope.additionalFieldSection.application_fields = utilityService.getInnerValue(data, 'data', 'application_fields', null);
                    $scope.additionalFieldSection.additional_fields = utilityService.getInnerValue(data, 'data', 'additional_fields', []);
                    if(cb) { cb(data); }
                });
        };
        $scope.attachFile = function(file, item) {
            if (file) {
                var isError = utilityService.validateFileSize(file, $scope.allowedFileSizeGlobal);
                if (isError) {
                    item.error = isError ? "File size must be less than or equal to " + $scope.allowedFileSizeGlobal.text : null;
                    item.value = null;
                } else {
                    item.value = file;
                    item.error = null;
                }
            } else {
                item.error = null;
                item.value = null;
            }
        };
        $scope.removeAttachment = function(item) {
            item.error = null;
            item.value = null;
        };
        $scope.saveAdditionalField = function() {
            $scope.saveAdditionalFieldIsDisabled = true;
            $scope.errorMessages = [];
            var url = service.getUrl('saveAdditionalField') + '/' + $scope.additionalFieldSection.candidate_id + '/' + $scope.additionalFieldSection.job_id;
            var payload = JobCommonService.buildApplyJobPayload($scope.additionalFieldSection.additional_fields, {value: {}});
            serverUtilityService.uploadWebService(url, payload)
                .then(function(data){
                    if (data.status == 'success') {
                        utilityService.showSimpleToast(data.message);
                        $scope.openModal('successOnAdditionalFieldsSubmission', 'success-on-additional-fields-submission.tmpl.html');
                        $scope.saveAdditionalFieldIsDisabled = false
                    } else {
                        if (data.status == 'error') {
                            $scope.errorMessages.push(data.message);
                        } else {
                            if(angular.isString(utilityService.getInnerValue(data, 'data', 'message'))) {
                                $scope.errorMessages.push(data.data.message);
                            } else {
                                angular.forEach(utilityService.getInnerValue(data, 'data', 'message'), function (v, k) {
                                    $scope.errorMessages.push(v[0]);
                                });
                            }
                        }
                    }
                });
        };
        $scope.closeSuccessModal = function() {
            $scope.closeModal('successOnAdditionalFieldsSubmission');
            $scope.goToDefaultJobs();
        };
        $scope.initializeAdditionalFieldSection = function() {
            $scope.additionalFieldSection.pageVisible = false;
            $scope.errorMessages = [];
            getAdditionalFields(function(data) {
                if(data.status == 'success') {
                    $scope.additionalFieldSection.pageExpire = false;
                } else {
                    if(angular.isString(data.message)) {
                        $scope.errorMessages.push(data.message);
                    } else {
                        if(angular.isString(utilityService.getInnerValue(data, 'data', 'message'))) {
                            $scope.errorMessages.push(data.data.message);
                        } else {
                            angular.forEach(utilityService.getInnerValue(data, 'data', 'message'), function (v, k) {
                                $scope.errorMessages.push(v[0]);
                            });
                        }
                    }
                    $scope.additionalFieldSection.pageExpire = true;
                }
                $scope.additionalFieldSection.pageVisible = true;
            });
        };
        $scope.initializeRecruitmentJobSection = function() {
            if($scope.isAdditionalFieldSectionActive()) {
                $scope.initializeAdditionalFieldSection();
            } else {
                $scope.goToDefaultJobs();
            }
        };
        $scope.initializeRecruitmentJobSection();
        $scope.openModal = function (instance, templateUrl, size) {
            size = size || 'md';
            $scope.modalInstance[instance] = $modal.open({
                templateUrl: templateUrl,
                scope: $scope,
                windowClass: 'fadeEffect',
                backdrop: 'static',
                keyboard: false,
                size: size
            });
        };
        $scope.closeModal = function (instance) {
            if ($scope.modalInstance[instance]) {
                $scope.modalInstance[instance].close();
            }
        };

        angular.element(document).ready(function () {
            $timeout(function(){
                $('#owl-carouselQandle').owlCarousel({
                    items:1,
                    stagePadding:50,
                    loop:true,
                    margin:10,
                    smartSpeed:450,
                });
                $('#owl-carouselQandlePartner').owlCarousel({
                    items:4,
                    loop:true,
                    autoplay:true,
                    margin:10,
                    smartSpeed:450,
                });

                $('.owl-dot').click(function () {
                    var n = $(this).index();
                    $(".owl-dot").removeClass("active");
                    $(this).addClass("active");
                    console.log(n);
                    $('#owl-carouselQandle').trigger('to.owl.carousel', n);
                });
            }, 3000);
        });
        $scope.openTermsAndPolicyPopup = function(ev) {
            $scope.openModal('termsNcondition.tmpl.html', 'termsAndCondition', 'lg');   
        }
        $scope.openDataRetentionPopup = function(ev) {
            $scope.openModal('dataRetention.tmpl.html', 'dataRetention', 'lg');   
        }

           /********* Start Angular Modal Section *********/
        $scope.openModal = function (templateUrl, instance, size) {
            size = angular.isDefined(size) ? size : 'md';
            $scope.modalInstance[instance] = $modal.open({
                templateUrl: templateUrl,
                scope: $scope,
                windowClass: 'fadeEffect',
                size: size,
                backdrop: 'static',
                keyboard: false
            });
        };
        $scope.closeModal = function (instance) {
            if (utilityService.getValue($scope.modalInstance, instance)) {
                $scope.modalInstance[instance].dismiss();
            }
        };
        /********* End Angular Modal Section *********/
        $scope.policie = false;
        var getTemsNPolciesData = function() {
        serverUtilityService.getWebService(service.getUrl('termsAndPolicies'))
        .then(function(data){
            if(data.data.visibility == true){
                $scope.policie = true;
                console.log($scope.policie)
            }else{
                $scope.policie = false;
                console.log($scope.policie)
            }
            $scope.policies.termsNcondition.content = data.data.content
        });
        }
        getTemsNPolciesData()

        $scope.RetentionPolicy = false;
        var getDataRetentionPolicy = function() {
        serverUtilityService.getWebService(service.getUrl('dataRetentionPolicy'))
        .then(function(data){
            if(data.data.enable_data_retention == true){
                $scope.RetentionPolicy = true;
                console.log($scope.RetentionPolicy)
            }else{
                $scope.RetentionPolicy = false;
                console.log($scope.RetentionPolicy)
            }
            $scope.policies.dataRetention.content = data.data.retention_policy_content
            $scope.policies.dataRetention.content_extended = data.data.retention_extent_content

        });
        }
        getDataRetentionPolicy()
    }
]);

app.controller('JobCommonController', [
    '$scope', '$routeParams', '$modal', '$location', '$timeout', 'utilityService', 'JobCommonService', 'ServerUtilityService', 'RecruitmentAdminService',
    function ($scope, $routeParams, $modal, $location, $timeout, utilityService, JobCommonService, serverUtilityService, RecruitmentAdminService) {
        var self = this;
        self.value = {};
        $scope.policyAccepted = false
        // angular.element("#erxes-messenger-iframe")[0].style.display = 'none';
        if (angular.element("#erxes-messenger-iframe") && angular.element("#erxes-messenger-iframe")[0]) {
            angular.element("#erxes-messenger-iframe")[0].style.display = 'none';
        }
        $scope.jobsObject = {
            isAllJobs: true,
            isJobDescription: false,
            isJobApply: false,
            isRefer: false,
            allJobsList: [],
            errorMessages: [],
            filterList: [],
            jobDetails: null,
            selectedJob: null,
            applyForm: null,
            parsedData: null,
            dummyItem: {},
            accessToken: utilityService.getStorageValue('accessToken'),
            employmentype: JobCommonService.buildEmploymentype(),
            pattern: {
                email: /^[a-zA-Z0-9-]+[a-zA-Z0-9._-]+@[a-zA-Z-]+\.[a-zA-Z.-]{2,20}$/,
                alphaNumeric: /^[0-9a-zA-Z \b]+$/
            },
            isDepartment: false
        };
        $scope.defaultJobObject = JobCommonService.buildDefaultJobObject();
        $scope.jobId = utilityService.getValue($routeParams, 'jobId');
        $scope.is_external = utilityService.getValue($routeParams, 'is_external');
        $scope.is_myReferral = utilityService.getValue($routeParams, 'my_refer');
        $scope.apply_now = utilityService.getValue($routeParams, 'apply_now');

        $scope.upButtonStatus = false;


        var extractItemObject = function () {
            var item = null;
            angular.forEach($scope.jobsObject.allJobsList, function (value, key) {
                if ($scope.jobId == value._id) {
                    item = value;
                }
            });
            if (item) {
                $scope.viewDetails(item, function () {
                    if ($scope.apply_now) {
                        $scope.jobsObject.isJobDescription = false;
                        $scope.applyJob(false);
                    } else {
                        $scope.jobsObject.isJobDescription = true;
                    }
                });
            }
        };

        var setJobListView = function (selectedJob) {
            $scope.viewJobList.visible = true;
            $scope.setBannerTitle(selectedJob);
        };
        var resetJobListView = function () {
            $scope.viewJobList.visible = false;
            $scope.setBannerTitle();
        };

        $scope.policyTermUpChange = function (policy) {
            if (policy != undefined && policy != null) {
                if (policy["termsNcondition"].check && policy["dataRetention"].check) {
                    $scope.upButtonStatus = true;
                } else {
                    $scope.upButtonStatus = false;
                }
            }
        }

        var parseJobDate = function (dateStr) {
            if (!dateStr || typeof dateStr !== 'string') return 0;
            var parsed = Date.parse(dateStr);
            if (!isNaN(parsed)) return parsed;
            parsed = Date.parse(dateStr.replace(/-/g, ' '));
            if (!isNaN(parsed)) return parsed;
            var months = {
                jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
                jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11
            };
            var parts = dateStr.trim().split(/[-/\s]+/);
            if (parts.length === 3) {
                var day = parseInt(parts[0], 10);
                var monthKey = parts[1].toLowerCase().slice(0, 3);
                var month = months[monthKey] !== undefined ? months[monthKey] : (parseInt(parts[1], 10) - 1);
                var year = parseInt(parts[2], 10);
                if (year < 100) year += 2000;
                var d = new Date(year, month, day);
                if (!isNaN(d.getTime())) return d.getTime();
            }
            return 0;
        };

        var getAllJobs = function () {
            var url = $scope.jobsObject.accessToken
                ? JobCommonService.getUrl('ijpJob') : JobCommonService.getUrl('allJobs');

            serverUtilityService.getWebService(url)
                .then(function (data) {
                    //data.data = JobCommonService.buildSampleJobResponse();
                    $scope.jobsObject.isDepartment = JobCommonService.isJobListHavingDepartment(utilityService.getValue(data, 'data', []));
                    angular.forEach(data.data, function (item) {
                        if (item.open_time) {
                            item.post_timestamp = item.open_time * 1000;
                        } else {
                            item.post_timestamp = parseJobDate(item.job_post_date);
                        }
                    });
                    $scope.jobsObject.allJobsList = data.data;
                    if ($scope.jobId) {
                        extractItemObject();
                    }
                });
        };
        getAllJobs();
        var getJobDetails = function (item) {
            if ($scope.is_external) {
                var url = JobCommonService.getUrl('jobDetails') + '/' + item._id + "?is_my_referral_request=" + true + '&requested_by=1';
            } else {
                url = JobCommonService.getUrl('jobDetails') + '/' + item._id;
            }
            serverUtilityService.getWebService(url)
                .then(function (data) {
                    $scope.jobsObject.jobDetails = data.data;
                    $scope.jobsObject.selectedJob = data.data.head;
                    setJobListView(data.data);
                });
        };
        var segmentFiledSyncRapper = function (v, k, job_details) {
            var def = "1970-01-01";
            if ((v.format_type == 1 || v.field_type == 10 || v.field_type == 12) && v.value) {
                v.value = v.value.toString();
            } else if (v.field_type == 5 && v.value != "") {
                v.value = utilityService.getDefaultDate(v.value);
            } else if (v.field_type == 13) {
                if (angular.isDefined(v.validator) && v.validator.is_multi_select == '1') {
                    self.value[v.slug] = [];
                    angular.forEach(self.allEmployees, function (val, ke) {
                        angular.forEach(v.value, function (id, index) {
                            if (id == val.id) {
                                self.value[v.slug].push(val);
                            }
                        });
                    });
                } else if (angular.isDefined(v.validator) && v.validator.is_multi_select == '0') {
                    angular.forEach(self.allEmployees, function (val, ke) {
                        if (v.value[0] == val.id) {
                            val.full_name = val.name;
                            val._id = val.id;
                            v.value = val;
                        }
                    });
                    if (!v.value.length && !angular.isObject(v.value)) {
                        v.value = null;
                        self[v.slug] = '';
                    }
                }
            } else if (v.field_type == 6) {
                v.value = new Date(def + " " + v.value);
            } else if (v.field_type == 11) {
                if (angular.isArray(v.value)) {
                    angular.forEach(v.element_details, function (v11, k11) {
                        v11.isChecked = v.value.indexOf(v11._id) == -1 ? false : true;
                    });
                }
            }
            if (!$scope.jobsObject.isRefer && job_details.internal_job_post && (v.slug == 'full_name' || v.slug == 'email')) {
                v.value = job_details[v.slug];
            }
        };
        var getApplyForm = function (item) {
            var tempUrl = $scope.jobsObject.accessToken
                ? JobCommonService.getUrl('ijpJob') : JobCommonService.getUrl('allJobs'),
                url = tempUrl + '/' + $scope.jobsObject.selectedJob._id+($scope.is_external?('?can_refer='+$scope.jobsObject.isRefer):'?can_refer=false');

            serverUtilityService.getWebService(url)
                .then(function (data) {
                    angular.forEach(data.data.application_field, function (v, k) {
                        segmentFiledSyncRapper(v, k, data.data.job_details);
                    });
                    $scope.jobsObject.applyForm = data.data;
                });
        };
        $scope.attachFile = function (file, item) {
            console.log(item)
            $scope.isFile = file
            if (file && $scope.envMnt != 'corrohealth') {
                var isError = utilityService.validateFileSize(file, $scope.allowedFileSizeGlobal);
                if (isError) {
                    item.error = isError ? "File size must be less than or equal to " + $scope.allowedFileSizeGlobal.text : null;
                    item.value = null;
                } else {
                    if ($scope.envMnt !== 'adukiaindustries') {
                        if (item.slug === 'cv' && item.field_type === 15) {
                            if (localStorage.getItem('accessToken')) {
                                parseCv(file)
                            } else {
                                parseCvOpen(file)
                            }
                        }
                    }

                    item.value = file;
                    item.error = null;
                }
                item.isUploaded = true;
            } else if ($scope.isInternal.internal_job_post && $scope.envMnt === 'corrohealth' && !file) {
                item.error = null;
                item.value = null;
            } else if ($scope.isInternal.internal_job_post && $scope.envMnt === 'corrohealth' && file) {
                item.error = null;
                item.value = file;
            } else if (!$scope.isInternal.internal_job_post && $scope.envMnt === 'corrohealth') {
                var isError = utilityService.validateFileSize(file, $scope.allowedFileSizeGlobal);
                if (isError) {
                    item.error = isError ? "File size must be less than or equal to " + $scope.allowedFileSizeGlobal.text : null;
                    item.value = null;
                } else {
                    if ($scope.envMnt !== 'adukiaindustries') {
                        if (item.slug === 'cv' && item.field_type === 15) {
                            if (localStorage.getItem('accessToken')) {
                                parseCv(file)
                            } else {
                                parseCvOpen(file)
                            }
                        }
                    }
                    item.value = file;
                    item.error = null;
                }
                item.isUploaded = true;
            } else {
                item.error = null;
                item.value = null;
            }
        };
        $scope.removeAttachment = function (item) {
            item.isUploaded = false;
            item.value = null;
        };

        var parseCvOpen = function (file) {
            $scope.loader = true
            var url = JobCommonService.getUrl('cvParserOpen') + '/' + $scope.jobsObject.selectedJob._id;
            var payload = {
                cv: file
            }
            serverUtilityService.uploadWebService(url, payload).then(function (data) {
                if (data.status == 'success') {
                    $scope.jobsObject.parsedData = data.data.parsed_data;
                    angular.forEach($scope.jobsObject.applyForm.application_field, function (val) {
                        // Check if there's data for this field's slug in the parsed response
                        if (data.data[val.slug]) {
                            // Handle phone field specially
                            if (val.slug === 'phone') {
                                val.value = data.data[val.slug];
                            }
                            // For array fields, join with commas; for strings, use as-is
                            else if (Array.isArray(data.data[val.slug])) {
                                val.value = data.data[val.slug].join(', ');
                            }
                            // For string fields, use directly
                            else {
                                val.value = data.data[val.slug] || '';
                            }
                        }

                        if (data.data.success_rate) {
                            $scope.weightage = data.data.success_rate
                        }
                    })

                    // Set ATS score from parsed data if available (not shown on frontend)
                    if (data.data.parsed_data && data.data.parsed_data.ats_score) {
                        $scope.jobsObject.ats_score = data.data.parsed_data.ats_score;
                    }

                } else {
                    console.log(data.message);
                }
            }).finally(function () {
                $scope.loader = false
            });
        }

        var parseCv = function (file) {
            $scope.loader = true
            var url = JobCommonService.getUrl('cvParserOpen') + '/' + $scope.jobsObject.selectedJob._id;
            var payload = {
                cv: file
